#!/usr/bin/env bash
set -euo pipefail
if [[ ! -f src/App.tsx || ! -f package.json ]]; then
  echo "ERROR: Run this script in your family-voice project directory." >&2
  exit 1
fi
if ! command -v node >/dev/null 2>&1; then
  echo "ERROR: Node.js is required." >&2
  exit 1
fi
node - <<'NODE'
const fs = require('fs');
const path = 'src/App.tsx';
const old = fs.readFileSync(path, 'utf8');
if (!old.includes('const roomFromUrl') || !old.includes('function createPeer()')) {
  throw new Error('This does not look like the expected Family Voice App.tsx. No changes made.');
}
if (old.includes('const [cameraOn, setCameraOn]')) {
  console.log('Camera support appears to be installed already. No files changed.');
  process.exit(0);
}
const next = Buffer.from('', 'base64').toString('utf8');
const backup = path + '.before-video.bak';
if (fs.existsSync(backup)) throw new Error('Backup already exists: ' + backup + '. Move it before rerunning.');
fs.copyFileSync(path, backup);
fs.writeFileSync(path, next);
console.log('Updated src/App.tsx; backup saved to ' + backup);
NODE
npm run build
printf '\nBuild passed. To deploy:\n  git add src/App.tsx\n  git commit -m "Add optional video calling"\n  git push\n'
